content.content:
    removed |= self.graph.get(n2, {}).pop(n1, None) is not None
    if removed:
        self.failed_links.append((n1, n2))
    return removed

def topology_discovery(self, net):
    """Build the controller's view of ``net`` (a Mininet instance).

    Registers every switch (with a flow table), every host (with its IP) and
    every link, and records the egress port each node uses towards its
    neighbour so installed rules carry real output ports.
    """
    for switch in net.switches:
        self.add_switch(switch.name)
    for host in net.hosts:
        self.add_host(host.name, host.ip)
    for link in net.links:
        node1, node2 = link.node1, link.node2
        self.add_link(node1.name, node2.name)
        self.ports[(node1.name, node2.name)] = link.port1
        self.ports[(node2.name, node1.name)] = link.port2
    return self.graph

def is_switch(self, name):
    """True when ``name`` is a registered switch."""
    return name in self.flow_tables

# ------------------------------------------------------------------
# path computation
# ------------------------------------------------------------------
def compute_path(self, src, dst):
    """Dijkstra shortest path from ``src`` to ``dst``.

    Returns the list of node names including both endpoints, or an empty
    list when the two nodes are not connected.  Equal-cost paths are broken
    deterministically in favour of the lexicographically smaller node.
    """
    src = getattr(src, "name", src)
    dst = getattr(dst, "name", dst)
    if src not in self.graph or dst not in self.graph:
        return []
    if src == dst:
        return [src]

    dist = {src: 0}
    prev = {src: None}
    visited = set()
    pq = [(0, src)]
    while pq:
        d, node = heapq.heappop(pq)
        if node in visited:
            continue
        visited.add(node)
        if node == dst:
            break
        for neighbour, weight in sorted(self.graph.get(node, {}).items()):
            if neighbour in visited:
                continue
            nd = d + weight
            if neighbour not in dist or nd < dist[neighbour]:
                dist[neighbour] = nd
                prev[neighbour] = node
                heapq.heappush(pq, (nd, neighbour))

    if dst not in prev:
        return []
    path = []
    node = dst
    while node is not None:
        path.append(node)
        node = prev[node]
    path.reverse()
    return path

def compute_all_paths(self):
    """``{(src, dst): path}`` for every ordered pair of known hosts."""
    paths = {}
    names = sorted(self.hosts, key=_name_key)
    for src in names:
        for dst in names:
            if src == dst:
                continue
            path = self.compute_path(src, dst)
            if path:
                paths[(src, dst)] = path
    return paths

def path_switches(self, path):
    """Registered switches traversed by ``path``, in order."""
    return [n for n in (path or []) if n in self.flow_tables]

